def is_90_ccw_rotation(grid_in, grid_out, center_r, center_c):
    """Check if output is grid_in rotated 90 CCW around center"""
    H, W = len(grid_in), len(grid_in[0])

    # Rotate each input cell
    rotated = set()
    for r in range(H):
        for c in range(W):
            if grid_in[r][c] != 0:
                dr = r - center_r
                dc = c - center_c
                nr = center_r + dc
                nc = center_c - dr
                if 0 <= nr < H and 0 <= nc < W:
                    rotated.add((nr, nc))

    # Compare with output
    output_set = set((r, c) for r in range(H) for c in range(W) if grid_out[r][c] != 0)
    return rotated == output_set

